package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {
  @TempDir Path tempDir;

  @Test
  void runWritesTheCompleteBuilderSource() throws Exception {
    Path output = tempDir.resolve("IncrementallyUpdatedFilterPredicateBuilder.java");

    new IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();

    assertTrue(Files.exists(output));
    String source = Files.readString(output, StandardCharsets.UTF_8);
    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.endsWith("}\n"));
    assertTrue(source.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends "
        + "IncrementallyUpdatedFilterPredicateBuilderBase"));
    assertTrue(source.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"));

    for (String operator : new String[] {"Eq", "NotEq", "In", "NotIn", "Contains", "Lt", "LtEq", "Gt", "GtEq"}) {
      assertEquals(operator.equals("Contains") ? 1 : 2, occurrences(source, "visit(" + operator + "<T> pred)"), operator);
    }
    assertEquals(1, occurrences(source, "visit(UserDefined<T, U> pred)"));
    assertEquals(1, occurrences(source, "visit(LogicalNotUserDefined<T, U> notPred)"));

    // Every supported primitive type has a generated branch for equality and membership.
    for (String type : new String[] {"Integer", "Long", "Boolean", "Float", "Double", "Binary"}) {
      assertTrue(source.contains("if (clazz.equals(" + type + ".class))"), type);
    }

    // NotIn is used by repeated columns too: it must remain undecided until a matching
    // value is observed, rather than returning false after the first non-match.
    int notInStart = source.indexOf("visit(NotIn<T> pred)");
    int containsStart = source.indexOf("  private abstract static class ContainsPredicate");
    String notIn = source.substring(notInStart, containsStart);
    assertTrue(notIn.contains("if (isKnown()) return;"));

    // Inequalities have explicit rejection for Boolean, which has no ordering in Parquet.
    for (String operator : new String[] {"<", "<=", ">", ">="}) {
      assertTrue(source.contains("Operator " + operator + " not supported for Boolean"));
    }

  }

  private static int occurrences(String text, String needle) {
    int count = 0;
    for (int at = 0; (at = text.indexOf(needle, at)) >= 0; at += needle.length()) {
      count++;
    }
    return count;
  }
}

